class Resource extends Vector {
 heading='A system that stays connected.';note='Move a node. The connections find their way around it.';
 build(){const count=this.number('detail',5,3,8);this.nodes??=Array.from({length:8},(_,i)=>({x:100+(i%3)*240,y:105+Math.floor(i/3)*110}));let connections='';for(let i=1;i<count;i++){const a=this.nodes[i-1],b=this.nodes[i],middle=(a.x+b.x)/2;connections+=`<path d="M${a.x} ${a.y}H${middle}V${b.y}H${b.x}" fill="none" stroke="#6f938e" stroke-width="1.3"/><circle cx="${middle}" cy="${b.y}" r="3" fill="${this.color}"/>`;if(i>2){const c=this.nodes[0];connections+=`<path d="M${c.x} ${c.y+26}V${b.y+38}H${b.x}V${b.y+26}" fill="none" stroke="#927e6344" stroke-dasharray="4 5"/>`;}}
 const names=['Source','Transform','Filter','Compose','Publish','Cache','Observe','Archive'];return this.svg(`<defs><pattern id="${this.artId}-grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="10" cy="10" r=".7" fill="#8fa39a2c"/></pattern></defs><rect x="20" y="20" width="680" height="380" rx="12" fill="#182824"/><rect x="20" y="20" width="680" height="380" rx="12" fill="url(#${this.artId}-grid)"/>${connections}${this.nodes.slice(0,count).map((p,i)=>`<g data-handle="${i}" tabindex="0" role="button" aria-label="${names[i]} node; use arrow keys to move"><rect x="${p.x-60}" y="${p.y-28}" width="120" height="56" rx="9" fill="#253e34" stroke="${i===0?this.color:'#5a7765'}"/><circle cx="${p.x-41}" cy="${p.y}" r="4" fill="${this.color}"/><text x="${p.x-26}" y="${p.y+4}" fill="#e2e3ce" font-family="system-ui" font-size="11">${names[i]}</text><circle cx="${p.x+60}" cy="${p.y}" r="3" fill="#b6c5a1"/></g>`).join('')}`);}
 interact(index,p){this.nodes[index]={x:clamp(p.x,85,635),y:clamp(p.y,65,355)};this.draw();this.emit('node-move',{index,...this.nodes[index]});}
 keyHandle(index,key,shift){const p=this.nodes[index],step=shift?25:8;this.interact(index,{x:p.x+(key==='ArrowRight'?step:key==='ArrowLeft'?-step:0),y:p.y+(key==='ArrowDown'?step:key==='ArrowUp'?-step:0)});}
}
